<script setup lang="ts">import Icon from '@/components/icons/Icon.vue';import UiButton from './UiButton.vue';import UiDateInput from './UiDateInput.vue';import UiFormField from './UiFormField.vue';import UiTimeInput from './UiTimeInput.vue';withDefaults(defineProps<{startDate:string;startTime:string;endDate:string;endTime:string;label?:string;description?:string;error?:string;presets?:{label:string;value:string}[]}>(),{presets:()=>[{label:'最近 1 小时',value:'1h'},{label:'今天',value:'today'},{label:'最近 7 天',value:'7d'}]});const emit=defineEmits<{'update:startDate':[string];'update:startTime':[string];'update:endDate':[string];'update:endTime':[string];preset:[string]}>();</script>
